function profSVG(h1,h2,L,o){o=o||{};const W=320,Hh=170,x0=40,x1=300,yTop=24,yBot=136;const mx=Math.max(h1,1),mn=Math.min(h2,0);const Y=h=>yBot-(h-mn)/(mx-mn)*(yBot-yTop);
  let s=LN(x0,yBot+0,x1,yBot,{sw:1,c:'var(--muted)'})+LN(x0,yTop-6,x0,yBot,{sw:1,c:'var(--muted)'});
  const pts=[];for(let i=0;i<=40;i++){const t=i/40;const h=h2+(h1-h2)*Math.pow(1-t,o.steep?2.4:1.6);pts.push([x0+t*(x1-x0),Y(h)]);}
  s+=PG([[x0,Y(mn)]].concat(pts).concat([[x1,Y(mn)]]),{f:'var(--hl)',fo:0.25});s+=PL(pts,{c:'var(--accent)',sw:3});
  if(mn<0)s+=LN(x0,Y(0),x1,Y(0),{sw:1,c:'var(--accent-ink)',dash:'4 3'})+TX(x0+4,Y(0)+11,'уровень океана 0 м',{fs:9.5,a:'start',c:'var(--accent-ink)',wt:500});
  s+=CI(x0,Y(h1),4,{f:'var(--ok)'})+TX(x0+6,Y(h1)-6,`исток ${N(h1)} м`,{fs:11,a:'start'})+CI(x1,Y(h2),4,{f:'var(--bad)'})+TX(x1-4,Y(h2)+(h2<0?14:-8),`устье ${N(h2)} м`,{fs:11,a:'end'});
  s+=ARR(x0-14,Y(h1),x0-14,Y(h2),{c:'var(--bad)',sw:1.5,hs:7})+TX(x0-18,(Y(h1)+Y(h2))/2,'падение',{fs:9.5,a:'end',c:'var(--bad)'});
  s+=LN(x0,yBot+14,x1,yBot+14,{sw:1})+TX((x0+x1)/2,yBot+28,`длина ${N(L)} км`,{fs:11});
  return SV(W+20,Hh+8,`<g transform="translate(20,0)">${s}</g>`,'Продольный профиль реки',o.wd||400);}
