G(9,()=>{const r=pick(['Волга','Нева','Ангара']);const [h1,h2,L]=PROF[r];const v=pick([3,4,5]);const d=pick([2,3,4]);const t=rnd(L/(v*24),1);
 return NUM(t,{q:`★ Плот сплавляют по реке ${r} от истока до устья (${N(L)} км). Скорость течения в среднем ${v} км/ч. Сколько суток займёт путь, если плыть круглосуточно? Округли до десятых.`,hint:'Время = путь : скорость; переведи часы в сутки.',short:`${N(L)} : ${v} : 24 ≈ ${N(t)} сут.`,
 explain:`${M(`${N(L)} : ${v} = ${N(rnd(L/v,1))} ч`)}; в сутках 24 ч: ${N(rnd(L/v,1))} : 24 ≈ <b>${N(t)}</b> суток.`,explain2:`Уклон реки ${N(rnd((h1-h2)*100/L,1))} см/км — ${r==='Нева'?'маленький, но Нева короткая и очень полноводная':'небольшой, поэтому течение спокойное'}.`});},{star:true});
G(9,()=>{const m=pick(SEA.filter(s=>s[2]>300));const V=Math.round(m[2]*1000*m[3]/1e3);
 return NUM(V,{q:`★ Площадь моря «${m[0]}» — ${N(m[2])} тыс. км², средняя глубина ${m[3]} м. Оцени объём воды в тыс. км³. Округли до целых.`,hint:'Объём = площадь × средняя глубина (переведи метры в км).',short:`${N(m[2])} тыс. км² · ${N(m[3]/1000)} км ≈ ${N(V)} тыс. км³.`,
 explain:`${m[3]} м = ${N(m[3]/1000)} км. ${M(`${N(m[2])} · ${N(m[3]/1000)} ≈ ${N(rnd(m[2]*m[3]/1000,1))}`)} тыс. км³ ≈ <b>${N(V)}</b>.`,explain2:'Как объём бассейна: длина × ширина × глубина. Площадь уже = длина × ширина.'});},{star:true});
/* ---------- interactive theory ---------- */
function onTheory(root){
  const w=root.querySelector('#w-map');
  if(w){const MP={'Баренцево':[40,72],'Белое':[37.8,65.6],'Карское':[77,75],'Лаптевых':[122,76],'Восточно-Сибирское':[155,73.5],'Чукотское':[186,69.3],'Берингово':[178,59],'Охотское':[148,55.5],'Японское':[136.5,43.2],'Балтийское':[19.5,56.8],'Чёрное':[35,43.4],'Азовское':[36.4,46.2]};
    const RM={'Волга':[46,51.5],'Обь':[76.6,60.9],'Иртыш':[72.2,56.9],'Енисей':[90.3,61.6],'Лена':[120.4,60.4],'Амур':[133,48.1],'Ангара':[101.6,56.3],'Северная Двина':[44,62.4],'Печора':[57.2,64],'Дон':[41.2,49.6],'Колыма':[152.5,65.5],'Кама':[53.5,56]};
    mapWidget(w,{title:'Карта вод: моря, реки, озёра',hint:'Нажми на точку — узнаешь, что это. «🎯» — игра «Найди на карте».',rivers:true,
     modes:{'Моря':SEA.map(m=>({k:m[0],name:m[0]+' море',lo:MP[m[0]][0],la:MP[m[0]][1],info:`${m[1]} океан; средняя глубина ${m[3]} м, макс. ${N(m[4])} м; порт ${m[5]}.`,c:'var(--accent-ink)'})).concat([{k:'kas',name:'Каспийское море-озеро',lo:50.6,la:45.5,info:'Бессточное солёное озеро, самое большое в мире.',c:'var(--accent-ink)'}]),
      'Реки':Object.keys(RM).map(r=>{const t=RIV.find(x=>x[0].indexOf(r)===0);return {k:r,name:'река '+r,lo:RM[r][0],la:RM[r][1],info:t?`Длина ${N(t[1])} км, сток ${t[3]} км³/год, бассейн: ${t[4]}${t[4].indexOf('стока')<0?' океан':''}.`:'',c:'var(--ok)'};}),
      'Озёра':[{k:'bai',name:'Байкал',lo:108,la:53.5,info:'1642 м — самое глубокое озеро мира, тектоническое; вытекает Ангара.'},{k:'lad',name:'Ладожское озеро',lo:31.5,la:60.8,info:'Самое большое пресное озеро Европы; вытекает Нева.'},{k:'one',name:'Онежское озеро',lo:35.4,la:61.8,info:'Ледниково-тектоническое; соединено Свирью с Ладогой.'},{k:'tai',name:'озеро Таймыр',lo:101,la:74.5,info:'Самое северное крупное озеро.'},{k:'xan',name:'озеро Ханка',lo:132.5,la:44.9,info:'На границе с Китаем.'},{k:'kas',name:'Каспийское море-озеро',lo:50.6,la:45.5,info:'≈ 390 тыс. км², уровень ≈ −27 м.'}].map(o=>Object.assign({c:'var(--bad)'},o))}});}
  const p=root.querySelector('#w-prof');
  if(p){let cur='Волга';p.innerHTML=`<b>Профиль реки: выбери реку или задай свою</b><div id="pb" style="display:flex;gap:6px;flex-wrap:wrap;margin:6px 0">${Object.keys(PROF).map(r=>`<button class="btn ghost" data-r="${r}" style="padding:5px 10px;font-size:14px">${r}</button>`).join('')}<button class="btn ghost" data-r="*" style="padding:5px 10px;font-size:14px">Своя река</button></div>
    <div id="pc" style="display:none"><label>Исток: <output id="o1"></output><input type="range" id="h1" min="50" max="3000" step="10" value="600"></label><label>Устье: <output id="o2"></output><input type="range" id="h2" min="-30" max="300" step="2" value="0"></label><label>Длина: <output id="o3"></output><input type="range" id="L" min="50" max="4000" step="10" value="800"></label></div>
    <div id="pp" class="fig"></div><div id="pt" style="text-align:center;line-height:1.7"></div>`;
    const g=id=>p.querySelector('#'+id);
    const u=()=>{let h1,h2,L,way='';if(cur==='*'){h1=+g('h1').value;h2=+g('h2').value;L=+g('L').value;g('o1').textContent=h1+' м';g('o2').textContent=h2+' м';g('o3').textContent=L+' км';}else{[h1,h2,L,way]=PROF[cur];}
      g('pc').style.display=cur==='*'?'block':'none';const P=h1-h2;g('pp').innerHTML=profSVG(h1,h2,L,{steep:cur==='Терек'});const um=P/L;
      g('pt').innerHTML=`${way?way+'<br>':''}Падение = ${N(h1)} − ${h2<0?'('+N(h2)+')':N(h2)} = <span class="out">${N(P)} м</span> · уклон = ${N(P)} : ${N(L)} = <span class="out">${um>=1?N(rnd(um,2))+' м/км':N(rnd(um*100,1))+' см/км'}</span><br><span class="small">${P<=0?'Исток должен быть выше устья!':um>=1?'Горная река: бурная, пороги, большие запасы гидроэнергии.':um>=0.3?'Река с заметным течением.':'Равнинная река: течёт спокойно, извилисто.'}</span>`;
      p.querySelectorAll('#pb button').forEach(b=>b.className='btn'+(b.dataset.r===cur?'':' ghost'));};
    g('pb').addEventListener('click',e=>{const b=e.target.closest('[data-r]');if(b){cur=b.dataset.r;u();}});['h1','h2','L'].forEach(id=>g(id).oninput=u);u();}
}
